/* Multi-page workspace extension. Core document import remains shared. */
const SECTIONS=[['intro','00','產品首頁','認識帳見'],['dashboard','01','財務總覽','日常管理'],['upload','02','帳單匯入',''],['transactions','03','交易明細',''],['budgets','04','分類預算',''],['cashflow','05','現金流',''],['accounts','06','帳戶與資產','資產規劃'],['portfolio','07','投資組合',''],['debts','08','負債與帳單',''],['goals','09','儲蓄目標',''],['news','10','每日新聞','資訊與工具'],['markets','11','股市資訊',''],['assistant','12','財務助理',''],['settings','13','設定與備份','']];
const ASSET_CLASSES=['現金與存款','台股與ETF','美股與ETF','基金','黃金','房地產','加密資產','其他'];
const WIDGET_NAMES={net:'淨資產快照',income:'本月收入',expense:'本月支出',budgets:'分類預算',goals:'儲蓄目標',bills:'近期應繳',allocation:'資產配置',recent:'最近交易'};
let ws={items:[],settings:{},snapshots:[],budgets:[],allocation:[],spending:{},cashflow:{},investment:{}},flowData={history:[],forecast:[]},txQuery='',txCategory='all',txDirection='all',txPage=1,newsData=null,assistantMode='local',conversation=[],assistantBusy=false,uiLoading=false;
let demoMode=false,monthRequest=0,newsTab='all',newsPoll=null,newsReadError='',newsReadAt='',newsReading=false,newsTicket=0;
const coreBind=bind,coreUpload=upload,coreEditTransaction=editTransaction;
const items=kind=>ws.items.filter(i=>i.kind===kind),esc=escapeHTML,number=v=>Number(v||0),today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Taipei'});
const plus=v=>(number(v)>0?'+':'')+fmt(v),pct=(a,b)=>number(b)?Math.max(0,Math.min(100,number(a)/number(b)*100)):0;
const btn=(label,attrs='',kind='')=>`<button class="btn ${kind}" ${attrs}>${label}</button>`;
const badge=(label,kind='')=>`<span class="ws-status ${kind}">${esc(label)}</span>`;
function wsHeader(title,kicker,description,actions=''){return `<div class="ws-head"><div><div class="ws-kicker">${kicker}</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`}
function empty(title,text,action=''){return `<div class="ws-empty"><h3>${title}</h3><p>${text}</p>${action}</div>`}
function pairs(rows){return rows.map(([a,b])=>`<div class="ws-pair"><span>${a}</span><strong>${b}</strong></div>`).join('')}
function meter(value,limit){return `<div class="ws-meter ${number(value)>number(limit)?'over':''}" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(pct(value,limit))}" aria-label="完成比例"><span style="width:${pct(value,limit)}%"></span></div>`}
function cardActions(item,extra=''){return `<div class="ws-card-actions">${btn('編輯',`data-item-edit="${esc(item.id)}"`)}${extra}${btn('刪除',`data-item-delete="${esc(item.id)}"`)}</div>`}
function monthControl(){const values=[...new Set([month,...db.transactions.map(t=>t.date.slice(0,7)),...items('budget').map(t=>t.month)])].sort().reverse();return `<input type="month" id="workspaceMonth" aria-label="統計月份" value="${month}" min="1900-01" max="2200-12">`}
reload=async function(){const ticket=++statsRequest,requested=month;const [data,stats,workspace,history]=await Promise.all([api('/api/state'),api('/api/stats?month='+requested),api('/api/workspace?month='+requested),api('/api/history?month='+requested)]);if(ticket!==statsRequest||requested!==month)return;db=data;summary=stats;ws=workspace;flowData=history;document.body.classList.toggle('dark',ws.settings.theme==='dark')};
goto=function(next){if(!SECTIONS.some(r=>r[0]===next))next='dashboard';if(busy||assistantBusy){notice('目前操作尚未完成，請稍候');return}if(next!=='news')stopNewsPolling();page=next;location.hash=next;lastError='';draw();window.scrollTo(0,0);if(next==='news')loadNews(false)};
function pageFooter(){const index=SECTIONS.findIndex(r=>r[0]===page),prev=SECTIONS[index-1],next=SECTIONS[index+1];return `<footer class="ws-footer"><p>帳見 LEDGER. 一塊一塊，看清你的財務。<br>${demoMode?'體驗工作區 · 合成資料，不代表個人財務':'本機工作區 · 文件匯入，資料留在你的裝置'}</p><div class="actions">${prev?btn('← '+prev[2],`data-page="${prev[0]}"`):''}${next?btn(next[2]+' →',`data-page="${next[0]}"`):''}</div></footer>`}
draw=function(){const selected=SECTIONS.find(r=>r[0]===page)||SECTIONS[1];el('#navigation').innerHTML=SECTIONS.map(([id,no,title,group])=>`${group?`<div class="nav-group">${group}</div>`:''}<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><b>${no}</b>${title}${id==='upload'&&pending.length?` <span class="badge">${pending.length}</span>`:''}</button>`).join('');const views={intro:wsIntro,dashboard:wsDashboard,upload:wsUpload,transactions:wsTransactions,budgets:wsBudgets,cashflow:wsCashflow,accounts:wsAccounts,portfolio:wsPortfolio,debts:wsDebts,goals:wsGoals,news:wsNews,markets:wsMarkets,assistant:wsAssistant,settings:wsSettings};el('#content').innerHTML=`<div class="ws-crumbs"><button data-page="intro">帳見</button><span>/</span><button data-page="dashboard">工作區</button><span>/</span><span>${selected[2]}</span></div>${lastError?`<div class="ws-callout ws-warning" role="alert">${esc(lastError)}</div>`:''}${demoMode?'<div class="ws-live-status"><span class="ws-status"><i></i>體驗工作區</span><span>合成資料，可操作各頁；PDF與雲端服務需啟動後端。</span></div>':''}${(views[page]||wsDashboard)()}${pageFooter()}`;bind()};
function wsIntro(){return `<nav class="ws-page-anchors" aria-label="產品首頁段落"><a href="#features" data-scroll="features">完整功能</a><a href="#workflow" data-scroll="workflow">如何使用</a><a href="#privacy" data-scroll="privacy">資料與隱私</a><a href="#faq" data-scroll="faq">常見問題</a></nav><section class="ws-intro-hero"><div><div class="ws-kicker">BUILD YOUR FINANCIAL CLARITY.</div><h1>把每一筆努力，<br>拼成生活的底氣。</h1><p>銀行帳單、信用卡與薪資，不必散落各處。<br>匯入、核對、看清收支，再為下一個目標留一塊。</p><div class="actions">${btn('進入我的儀表板 →','data-page="dashboard"','primary')}${btn('先看怎麼匯入','data-page="upload"')}</div></div><img src="assets/brick-finance-team-preview.webp" width="1536" height="1024" alt="積木銀行經理與上班族一起整理財務"></section><section id="features"><div class="section-head"><h2>不只記帳，是一個完整財務工作區。</h2><span class="ws-kicker">13 CONNECTED VIEWS</span></div><div class="ws-feature-grid">${[['upload','文件匯入','PDF / CSV → 辨識 → 覆核，確認後才計入。'],['budgets','預算與現金流','分類額度、實際支出、餘額和月份走勢。'],['portfolio','資產與投資','手動持倉、成本市值、目標配置與再平衡。'],['debts','負債與應繳','信用卡帳單、貸款攤還和繳費提醒。'],['goals','儲蓄目標','備用金、進修或旅行，讓每一步有進度。'],['assistant','資訊與資料助理','官方RSS與本機查詢；可選擇啟用雲端AI。']].map(([id,title,text],i)=>`<button class="ws-card" data-page="${id}"><span class="ws-kicker">0${i+1} / EXPLORE</span><h3>${title} ↗</h3><p class="ws-muted">${text}</p></button>`).join('')}</div></section><section id="workflow" class="ws-card"><h2>三步，讓數字回到同一張圖上。</h2><div class="ws-grid"><div><span class="ws-kicker">01 / IMPORT</span><h3>放進帳單</h3><p>匯入支援的文字PDF或CSV；未知版型會明確提示。</p></div><div><span class="ws-kicker">02 / REVIEW</span><h3>核對每一筆</h3><p>檢查金額、分類與重複交易，確認後寫入帳本。</p></div><div><span class="ws-kicker">03 / PLAN</span><h3>開始規劃</h3><p>看收支、分配預算、追蹤目標，所有頁面共同更新。</p></div></div></section><section id="privacy" class="ws-callout"><strong>不綁網銀，不索取銀行密碼。</strong><br>預設使用本機資料。雲端AI只有在設定Key並明確同意後，才傳送所選期間的彙總資料與提問；不會自動執行交易。</section><section id="faq"><h2>先回答你可能在想的。</h2>${[['每一家銀行PDF都能讀嗎？','目前支援已驗證的文字版型與標準CSV。掃描OCR與任意版型尚未完成；失敗會拒絕，不產生猜測數字。'],['哪些功能現在可以操作？','帳單覆核、交易編輯、帳戶、分類預算、現金流、手動投資、目標配置、負債攤還、提醒與儲蓄目標均連到儲存層。體驗模式使用合成資料。'],['價格、新聞與AI都會自動更新嗎？','持倉價格與匯率目前手動更新並顯示日期。新聞依每日設定時間或手動刷新，需後端持續運行。雲端AI需另設有效API Key。'],['是不是投資建議？','配置差額與XIRR依你輸入的數據計算，不代表買賣建議或報酬保證。']].map(([q,a])=>`<details class="ws-faq"><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`}
function wsDashboard(){const cash=ws.cashflow||{},budgets=ws.budgets||[],goals=items('goal'),bills=upcomingBills(),alloc=ws.allocation||[];const widgets={net:`<article class="ws-card yellow-card"><div class="ws-kicker">NET WORTH / 帳戶淨值</div><div class="ws-figure">${fmt(ws.net_worth)}</div>${pairs([['總資產',fmt(ws.assets)],['總負債',fmt(ws.liabilities)]])}<p class="ws-caption" style="margin-top:12px;color:#514927">依已匯入快照、手動資產與持倉計算，不再累加交易流水。</p></article>`,income:`<article class="ws-card blue-card"><div class="ws-kicker">MONEY IN / 本月收入</div><div class="ws-figure">${fmt(cash.income)}</div><p>薪資與股息，扣除同分類負數更正。</p><button class="btn small" data-page="cashflow" style="margin-top:18px">查看現金流 ↗</button></article>`,expense:`<article class="ws-card"><div class="ws-kicker">MONEY OUT / 本月支出</div><div class="ws-figure">${fmt(cash.expense)}</div><p class="ws-muted">本月結餘 <strong class="mono">${plus(cash.balance)}</strong></p><p class="ws-caption" style="margin-top:15px">轉帳、投資入出金及繳卡費不重複計入收支。</p></article>`,budgets:`<article class="ws-card"><div class="ws-card-head"><h2>這個月，留一點餘裕。</h2><button class="textbtn" data-page="budgets">預算 ↗</button></div>${budgets.length?budgets.slice(0,3).map(b=>`<div style="margin-top:15px"><div class="ws-line ws-pair"><span>${esc(b.category)}</span><strong>${fmt(b.used)} / ${fmt(b.limit)}</strong></div>${meter(b.used,b.limit)}</div>`).join(''):'<p class="ws-caption">先設定分類預算，這裡會跟著實際交易更新。</p>'}</article>`,goals:`<article class="ws-card"><div class="ws-card-head"><h2>為想要的生活，存一塊。</h2><button class="textbtn" data-page="goals">目標 ↗</button></div>${goals.length?goals.slice(0,2).map(g=>`<div style="margin-top:16px"><div class="ws-pair"><span>${esc(g.name)}</span><strong>${Math.round(pct(g.saved,g.target))}%</strong></div>${meter(g.saved,g.target)}<div class="ws-caption">${fmt(g.saved)} / ${fmt(g.target)}</div></div>`).join(''):'<p class="ws-caption">建立第一個儲蓄目標，開始記錄進度。</p>'}</article>`,bills:`<article class="ws-card"><div class="ws-card-head"><h2>接下來，記得這幾筆。</h2><button class="textbtn" data-page="debts">應繳 ↗</button></div>${bills.slice(0,3).map(b=>`<div class="ws-pair"><span>${esc(b.name)}<br><small class="ws-muted">${esc(b.due)}</small></span><strong>${fmt(b.amount)}</strong></div>`).join('')||'<p class="ws-caption">目前沒有待繳記錄；不代表已確認沒有欠款。</p>'}</article>`,allocation:`<article class="ws-card"><div class="ws-card-head"><h2>錢，放在哪裡？</h2><button class="textbtn" data-page="portfolio">配置 ↗</button></div>${alloc.filter(a=>number(a.value)>0).map(a=>`<div class="ws-bar-item"><div class="ws-pair"><span>${esc(a.asset_class)}</span><strong>${number(a.actual).toFixed(1)}%</strong></div><div class="ws-bar-track"><span style="width:${Math.min(100,number(a.actual))}%"></span></div></div>`).join('')||'<p class="ws-caption">新增帳戶與持倉後顯示配置。</p>'}</article>`,recent:`<article class="ws-card"><div class="ws-card-head"><h2>最近入帳</h2><button class="textbtn" data-page="transactions">全部 ↗</button></div>${db.transactions.filter(t=>t.date.startsWith(month)).slice(0,4).map(t=>`<div class="ws-pair"><span>${esc(t.name)}<br><small class="ws-muted">${esc(t.date)}</small></span><strong>${plus(t.amount)}</strong></div>`).join('')||'<p class="ws-caption">這個月份還沒有交易。</p>'}</article>`};const order=ws.settings.widgets||Object.keys(WIDGET_NAMES);return wsHeader('看清今天，拼好明天。','THE BIG PICTURE','每個面板都有來處，也能往下看明細。',monthControl()+btn('自訂面板','id="layoutButton"')+btn('＋ 匯入帳單','data-page="upload"','primary'))+brickIntro()+`<div class="ws-grid">${order.filter(k=>widgets[k]).map(k=>`<section draggable="true" data-widget="${k}" aria-label="${WIDGET_NAMES[k]}，可拖拉或從自訂面板排序">${widgets[k]}</section>`).join('')}</div><div class="ws-card"><div class="ws-card-head"><h2>淨值快照</h2>${btn('記錄今日快照','id="takeSnapshot"')}</div>${ws.snapshots.length>1?`<div class="ws-trend-area"><div class="ws-trend">${ws.snapshots.slice(-12).map(s=>`<div style="height:${Math.max(5,Math.abs(number(s.net_worth))/Math.max(1,...ws.snapshots.map(x=>Math.abs(number(x.net_worth))))*100)}px" title="${esc(s.day)}：${fmt(s.net_worth)}"><small>${esc(s.day.slice(5))}</small></div>`).join('')}</div></div><p class="ws-caption">柱高為淨值絕對值；完整帶正負數值如下：${ws.snapshots.slice(-12).map(s=>esc(s.day)+' '+fmt(s.net_worth)).join(' · ')}</p>`:'<p class="ws-caption">尚未累積足夠日期。按「記錄今日快照」後保存當日已知數字，不會製造歷史曲線。</p>'}</div>`}
function wsUpload(){return coreUpload()+`<section class="ws-card" style="margin-top:28px"><h2>你的文件紀錄</h2>${db.imports.length?`<div class="ws-table"><table><thead><tr><th>文件</th><th>確認交易</th><th>狀態</th><th>明細</th></tr></thead><tbody>${db.imports.map(i=>`<tr><td class="ws-wrap">${esc(i.name)}</td><td>${i.count} 筆</td><td>${badge('已確認','success')}</td><td><button class="textbtn" data-document-source="${esc(i.document_id)}">原始欄位 ↗</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="ws-caption">文件確認後，會在這裡留下來源與核對資訊。</p>'}</section>`}
function filteredTransactions(){return db.transactions.filter(t=>t.date.startsWith(month)&&(!txQuery||(t.name+' '+t.source+' '+t.category).toLowerCase().includes(txQuery.toLowerCase()))&&(txCategory==='all'||t.category===txCategory)&&(txDirection==='all'||(txDirection==='in'?number(t.amount)>0:number(t.amount)<0))).sort((a,b)=>b.date.localeCompare(a.date))}
function transactionRows(){const rows=filteredTransactions(),count=Math.max(1,Math.ceil(rows.length/15));txPage=Math.min(txPage,count);return table(rows.slice((txPage-1)*15,txPage*15),true)+`<div class="ws-pagination"><span>共 ${rows.length} 筆 · 第 ${txPage} / ${count} 頁</span><div class="actions">${btn('← 上一頁',`data-tx-page="${txPage-1}" ${txPage===1?'disabled':''}`)}${btn('下一頁 →',`data-tx-page="${txPage+1}" ${txPage===count?'disabled':''}`)}</div></div>`}
function wsTransactions(){return wsHeader('每一筆，都能追得回去。','TRANSACTION LEDGER','搜尋、篩選、修改分類與金額，統計會共同更新。',monthControl()+btn('匯出篩選結果','id="filteredCSV"')+btn('＋ 手動新增','id="manualTransaction"','primary'))+`<div class="ws-filter"><input id="txSearch" aria-label="搜尋交易" placeholder="搜尋商家、摘要、分類或來源" value="${esc(txQuery)}"><select id="txCategory" aria-label="交易分類"><option value="all">全部分類</option>${cats.map(c=>`<option ${txCategory===c?'selected':''}>${c}</option>`).join('')}</select><select id="txDirection" aria-label="收支方向"><option value="all">全部金額</option><option value="in" ${txDirection==='in'?'selected':''}>正數入帳</option><option value="out" ${txDirection==='out'?'selected':''}>負數扣款</option></select></div><div id="transactionResults">${transactionRows()}</div><div class="ws-callout">消費分類的正數退款抵減支出；薪資與股息負數抵減收入。若改錯分類，統計也會跟著改變，請核對來源。</div>`}
function wsBudgets(){const budgets=ws.budgets||[],limit=budgets.reduce((s,b)=>s+number(b.limit),0),used=budgets.reduce((s,b)=>s+number(b.used),0);return wsHeader('替這個月，留一點空間。','CATEGORY BUDGETS','預算不修改帳戶餘額；支出直接連到已入帳交易。',monthControl()+btn('沿用上月','id="copyBudgets"')+btn('＋ 新增分類預算','data-add-kind="budget"','primary'))+`<div class="ws-grid"><div class="ws-card yellow-card"><span class="ws-kicker">PLANNED / 分類額度</span><div class="ws-figure">${fmt(limit)}</div></div><div class="ws-card"><span class="ws-kicker">SPENT / 已設預算分類支出</span><div class="ws-figure">${fmt(used)}</div></div><div class="ws-card"><span class="ws-kicker">AVAILABLE / 剩餘額度</span><div class="ws-figure">${fmt(limit-used)}</div></div></div>${budgets.length?`<div class="ws-grid two">${budgets.map(b=>`<article class="ws-card"><div class="ws-card-head"><h3>${esc(b.category)}</h3>${number(b.used)>number(b.limit)?badge('超出 '+fmt(number(b.used)-number(b.limit)),'alert'):badge('剩餘 '+fmt(b.remaining))}</div><div class="ws-figure">${fmt(b.used)} <small class="ws-muted" style="font-size:13px">/ ${fmt(b.limit)}</small></div>${meter(b.used,b.limit)}<button class="textbtn" data-spending-category="${esc(b.category)}">查看這個分類的交易 ↗</button>${cardActions(b)}</article>`).join('')}</div>`:empty('先替常花的幾項，設一個範圍。','例如餐飲、交通、生活與保險。',btn('設定第一筆預算','data-add-kind="budget"','primary'))}<div class="ws-callout">轉帳、投資入出金與信用卡繳款不占用消費預算；沒有設定預算的分類，仍會正常計入總支出。</div>`}
function wsCashflow(){const history=flowData.history||[],max=Math.max(1,...history.flatMap(h=>[Math.abs(number(h.income)),Math.abs(number(h.expense))]));return wsHeader('錢怎麼進來，又往哪裡去。','CASH FLOW','從月份與分類看收支，不把轉帳當成消費。',monthControl())+`<div class="ws-grid"><div class="ws-card blue-card"><span class="ws-kicker">INCOME</span><div class="ws-figure">${fmt(summary.income)}</div></div><div class="ws-card"><span class="ws-kicker">SPENDING</span><div class="ws-figure">${fmt(summary.expense)}</div></div><div class="ws-card yellow-card"><span class="ws-kicker">SURPLUS</span><div class="ws-figure">${plus(summary.balance)}</div></div></div><div class="ws-grid two"><section class="ws-card"><h2>最近六個月</h2><div class="ws-columns">${history.map(h=>`<div class="ws-col" role="group" aria-label="${h.month} 收入${fmt(h.income)}支出${fmt(h.expense)}"><span style="height:${Math.abs(number(h.income))/max*100}%"></span><span style="height:${Math.abs(number(h.expense))/max*100}%"></span><label>${h.month.slice(2)}</label><button data-select-month="${h.month}" aria-label="查看${h.month}"></button></div>`).join('')}</div><div class="ws-legend"><span><i></i>收入</span><span><i class="yellow"></i>支出</span></div><p class="ws-caption">柱高為金額絕對值。若有負數更正，請以下方帶正負數表格為準。</p></section><section class="ws-card"><h2>本月消費結構</h2>${Object.entries(ws.spending||{}).map(([category,value])=>`<div class="ws-bar-item"><button data-spending-category="${esc(category)}"><div class="ws-pair"><span>${esc(category)} ↗</span><strong>${fmt(value)}</strong></div><div class="ws-bar-track"><span style="width:${pct(Math.abs(number(value)),Math.max(1,...Object.values(ws.spending).map(v=>Math.abs(number(v)))))}%"></span></div></button></div>`).join('')}</section></div><div class="ws-table"><table><thead><tr><th>月份</th><th>收入</th><th>支出</th><th>結餘</th><th>已入帳筆數</th></tr></thead><tbody>${history.map(h=>`<tr><td>${h.month}</td><td class="amount">${fmt(h.income)}</td><td class="amount">${fmt(h.expense)}</td><td class="amount">${plus(h.balance)}</td><td>${h.transaction_count}</td></tr>`).join('')}</tbody></table></div><section class="ws-card" style="margin-top:25px"><h2>未來三個月 · 固定均值情境試算</h2>${flowData.forecast.length?pairs(flowData.forecast.map(f=>[f.month+' 預估收支結餘',plus(f.balance)])):'<p class="ws-muted">至少需要三個已結束月份有交易，才提供均值試算。目前不補造缺少月份。</p>'}<p class="ws-caption" style="margin-top:15px">${esc(flowData.assumption||'此為條件試算，不是對未來收入或支出的保證。')}</p></section>`}
function wsAccounts(){const manual=items('account');return wsHeader('把散落的資產，放回同一張圖。','ACCOUNTS & ASSETS','帳單快照與手動帳戶分開標示；同名項目會阻擋重複計入。',btn('＋ 手動資產','data-add-kind="account"','primary'))+`<div class="ws-grid"><div class="ws-card yellow-card"><span class="ws-kicker">TOTAL ASSETS</span><div class="ws-figure">${fmt(ws.assets)}</div><p>含已匯入帳戶、手動資產與持倉。</p></div><div class="ws-card"><span class="ws-kicker">IMPORTED ACCOUNTS</span><div class="ws-figure">${db.assets.length}</div><p class="ws-muted">以文件期末餘額為準。</p></div><div class="ws-card"><span class="ws-kicker">MANUAL ACCOUNTS</span><div class="ws-figure">${manual.length}</div><p class="ws-muted">定存、現金或其他手動快照。</p></div></div><h2>從文件匯入</h2>${db.assets.length?`<div class="ws-grid two">${db.assets.map(a=>`<article class="ws-card"><span class="ws-kicker">STATEMENT SNAPSHOT</span><h3 style="margin-top:10px">${esc(a.name)}</h3><div class="ws-figure">${fmt(a.value)}</div><p class="ws-caption">${esc(a.as_of||'日期未知')} · ${esc(a.source||'上傳文件')}</p>${btn('查看文件紀錄','data-page="upload"')}</article>`).join('')}</div>`:empty('還沒有帳戶快照','匯入銀行對帳單，或先手動新增資產。',btn('匯入帳單','data-page="upload"'))}<h2>手動資產</h2>${manual.length?`<div class="ws-grid two">${manual.map(a=>`<article class="ws-card"><div class="ws-card-head"><h3>${esc(a.name)}</h3>${badge(a.asset_class)}</div><div class="ws-figure">${fmt(a.value)}</div><p class="ws-caption">手動更新日期 ${esc(a.as_of)}</p>${cardActions(a)}</article>`).join('')}</div>`:'<p class="ws-caption">目前沒有手動資產。</p>'}<div class="ws-callout">同一筆資金請選擇匯入帳戶或手動資產之一；持倉已在投資組合計價，不要再新增同一筆證券帳戶總額。</div>`}
function wsPortfolio(){const holdings=items('holding'),investment=ws.investment||{},flows=items('investment_flow');return wsHeader('讓每一塊配置，都有位置。','PORTFOLIO & REBALANCE','持倉價格與匯率手動填寫，顯示估值日期；不會自動買賣。',btn('設定目標配置','id="allocationTargets"')+btn('＋ 新增持倉','data-add-kind="holding"','primary'))+`<div class="ws-grid"><div class="ws-card blue-card"><span class="ws-kicker">MARKET VALUE / 手動估值</span><div class="ws-figure">${fmt(investment.value)}</div></div><div class="ws-card"><span class="ws-kicker">COST BASIS / 換算成本</span><div class="ws-figure">${fmt(investment.cost)}</div></div><div class="ws-card yellow-card"><span class="ws-kicker">UNREALIZED / 試算價差</span><div class="ws-figure">${plus(investment.unrealized)}</div></div></div>${holdings.length?`<div class="ws-table"><table><thead><tr><th>持倉</th><th>分類</th><th>數量</th><th>單位成本／現價</th><th>TWD市值</th><th>估值日期</th><th>操作</th></tr></thead><tbody>${holdings.map(h=>`<tr><td>${esc(h.name)}<br><span class="ws-caption">${esc(h.symbol)}</span></td><td>${esc(h.asset_class)}</td><td class="mono">${esc(h.quantity)}</td><td class="mono">${fmt(h.cost_price)} / ${fmt(h.price)} ${h.currency}</td><td class="amount">${fmt(h.value)}</td><td class="mono">${esc(h.as_of)}</td><td><button class="textbtn" data-item-edit="${h.id}">編輯</button> <button class="textbtn" data-item-delete="${h.id}">刪除</button></td></tr>`).join('')}</tbody></table></div>`:empty('先放進一筆持倉。','可記錄台股、美股、ETF、基金與其他資產；外幣需填匯率。',btn('新增持倉','data-add-kind="holding"','primary'))}<section class="ws-card" style="margin-top:25px"><div class="ws-card-head"><h2>實際配置 vs. 你的目標</h2>${btn('調整目標','id="allocationTargetsSecond"')}</div>${ws.allocation.length?`<div class="ws-table"><table><thead><tr><th>資產類別</th><th>目前金額</th><th>實際比例</th><th>目標</th><th>試算調整金額</th></tr></thead><tbody>${ws.allocation.map(a=>`<tr><td>${esc(a.asset_class)}</td><td class="amount">${fmt(a.value)}</td><td class="amount">${number(a.actual).toFixed(1)}%</td><td class="amount">${ws.settings.targets?esc(a.target)+'%':'尚未設定'}</td><td class="amount">${a.difference===null?'—':plus(a.difference)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="ws-caption">有資產後才會計算實際比例。</p>'}<p class="ws-caption" style="margin-top:14px">目標金額以整分分配，合計保持總資產；差額未計稅費、匯差與成交成本。成本也使用當前自填匯率，並非完整已實現報酬。</p></section><section class="ws-card" style="margin-top:25px"><div class="ws-card-head"><h2>XIRR 投資現金流</h2><div class="actions">${btn('計算XIRR','id="calculateXirr"')}${btn('＋ 現金流','data-add-kind="investment_flow"')}</div></div><p class="ws-caption">投入填負數、收回與期末估值填正數。多次現金流方向改變時，此版會拒絕輸出可能不唯一的答案。</p>${flows.length?pairs(flows.map(f=>[esc(f.date)+' · '+esc(f.name),plus(f.amount)+` <button class="textbtn" data-item-edit="${f.id}">編輯</button>`])):'<p class="ws-caption" style="margin-top:15px">尚無投資現金流記錄。</p>'}<div id="xirrResult" aria-live="polite"></div></section>`}
function upcomingBills(){return [...db.debts.map(d=>({name:d.name,amount:d.payment||d.balance,due:d.due,imported:true})),...items('debt').map(d=>({name:d.name,amount:d.payment,due:d.due,loan:true})),...items('bill').filter(b=>b.status!=='paid')].sort((a,b)=>a.due.localeCompare(b.due))}
function wsDebts(){const loans=items('debt'),bills=items('bill');return wsHeader('把應繳與還款，排進生活。','DEBTS, BILLS & REMINDERS','負債快照計入淨值；提醒本身不會再加一筆負債或支出。',btn('＋ 繳費提醒','data-add-kind="bill"')+btn('＋ 手動貸款','data-add-kind="debt"','primary'))+`<div class="ws-grid"><div class="ws-card red-card"><span class="ws-kicker">LIABILITIES / 總負債</span><div class="ws-figure">${fmt(ws.liabilities)}</div><p>已匯入卡債與手動貸款本金。</p></div><div class="ws-card"><span class="ws-kicker">UPCOMING / 待繳記錄</span><div class="ws-figure">${upcomingBills().length} 筆</div><p class="ws-caption">此為記錄數，可能屬於不同付款期間。</p></div><div class="ws-card"><span class="ws-kicker">NEXT DUE / 最近截止</span><div class="ws-figure" style="font-size:23px">${upcomingBills()[0]?.due||'尚無記錄'}</div><p class="ws-caption">只在頁面顯示，未啟用系統背景推播。</p></div></div><h2>信用卡帳單</h2><div class="ws-grid two">${db.debts.map(d=>`<article class="ws-card"><h3>${esc(d.name)}</h3><div class="ws-figure">${fmt(d.payment||d.balance)}</div>${pairs([['最低應繳',d.minimum_payment===undefined?'未提供':fmt(d.minimum_payment)],['繳款截止',esc(d.due)],['文件日期',esc(d.as_of||'未提供')]])}<p class="ws-caption">來源 ${esc(d.source||'上傳文件')}</p>${btn('查看帳單','data-page="upload"')}</article>`).join('')||'<p class="ws-caption">尚無信用卡快照。</p>'}</div><h2>手動貸款</h2><div class="ws-grid two">${loans.map(d=>`<article class="ws-card"><h3>${esc(d.name)}</h3><div class="ws-figure">${fmt(d.balance)}</div>${pairs([['固定年利率',esc(d.rate)+'%'],['每月還款',fmt(d.payment)],['下次到期',esc(d.due)]])}${cardActions(d,btn('攤還試算',`data-schedule="${d.id}"`))}</article>`).join('')||'<p class="ws-caption">尚未新增貸款。</p>'}</div><h2>繳費提醒</h2>${bills.length?`<div class="ws-grid two">${bills.map(b=>`<article class="ws-card"><div class="ws-card-head"><h3>${esc(b.name)}</h3>${badge(b.status==='paid'?'已標記繳清':'待繳',b.status==='paid'?'success':'')}</div><div class="ws-figure">${fmt(b.amount)}</div><p class="ws-caption">${esc(b.due)} · ${b.recurrence==='monthly'?'每月':b.recurrence==='yearly'?'每年':'單次'}</p>${cardActions(b,btn(b.status==='paid'?'標記未繳':'標記繳清',`data-bill-toggle="${b.id}"`)+(b.recurrence!=='none'?btn('產生下期',`data-bill-next="${b.id}"`):''))}</article>`).join('')}</div>`:empty('需要記得的事，先放在這裡。','房租、保費或卡費提醒；不會自動產生付款。',btn('新增提醒','data-add-kind="bill"'))}`}
function wsGoals(){const goals=items('goal');return wsHeader('為你想要的生活，存一塊。','SAVINGS GOALS','目標進度獨立記錄，不會把同一筆存款再加進總資產。',btn('＋ 新增目標','data-add-kind="goal"','primary'))+`${goals.length?`<div class="ws-grid two">${goals.map(g=>`<article class="ws-card"><div class="ws-card-head"><h3>${esc(g.name)}</h3>${badge(Math.round(pct(g.saved,g.target))+'% 達成',number(g.saved)>=number(g.target)?'success':'')}</div><div class="ws-figure">${fmt(g.saved)}</div><p class="ws-caption">目標 ${fmt(g.target)} · ${g.deadline?'希望在 '+esc(g.deadline)+' 達成':'未設定期限'}</p>${meter(g.saved,g.target)}<p class="ws-caption">還差 ${fmt(Math.max(0,number(g.target)-number(g.saved)))}</p>${cardActions(g,btn('更新已存金額',`data-goal-fund="${g.id}"`))}</article>`).join('')}</div>`:empty('先選一個，值得期待的目標。','緊急備用金、旅行、進修，或你自己的下一步。',btn('建立目標','data-add-kind="goal"','primary'))}<section class="ws-card"><h2>緊急備用金參考</h2>${number(summary.expense)>0?pairs([['以所選月份支出3倍計算',fmt(number(summary.expense)*3)],['以所選月份支出6倍計算',fmt(number(summary.expense)*6)]]):'<p class="ws-caption">目前月份沒有正支出，暫不推算金額。</p>'}<p class="ws-caption">這是單月支出倍數的算術參考；資料不完整或當月異常支出會影響結果，不代表個人適用的建議。</p></section>`}
function newsTime(value){if(!value)return '尚無紀錄';const date=new Date(value);return Number.isNaN(date.getTime())?String(value):date.toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false})}
function newsConnectionPanel(){const schedule=newsData?.schedule||ws.settings.news_schedule||{enabled:true,hour:8,minute:0},time=String(schedule.hour).padStart(2,'0')+':'+String(schedule.minute).padStart(2,'0'),channels=Object.values(newsData?.channels||{}),available=channels.filter(c=>c.items?.length),last=available.map(c=>c.updated_at).filter(Boolean).sort().at(-1),attempt=[newsData?.job?.started_at,...channels.map(c=>c.last_attempt)].filter(Boolean).sort().at(-1),ai=available.filter(c=>c.ai_generated).length;return `<section class="ws-card" aria-label="每日新聞更新狀態"><h2>每日新聞更新狀態</h2>${pairs([['自動更新',demoMode?'未啟動：互動體驗不執行背景排程':schedule.enabled?'已設定；需後端持續運行':'已關閉'],['排程設定',esc(time)+' / 台灣時間'+(demoMode?'（僅設定值，未執行）':'')],['最後取得內容',last?esc(newsTime(last)):'尚未成功取得新聞'],['最後嘗試更新',attempt?esc(newsTime(attempt)):'尚無更新嘗試紀錄'],['畫面最後同步',newsReadAt?esc(newsTime(newsReadAt)):'尚未讀取最新狀態'],['AI新聞摘要',ai===2?'兩個分類已有摘要；完整性請看各分類來源狀態':ai?'僅部分分類已有摘要':'尚未產生']])}${newsReadError?`<div class="ws-callout ws-warning" role="alert">${esc(newsReadError)}${newsData?'；下方保留上次已讀取的內容，未確認為最新狀態。':'；目前沒有可顯示的新聞內容。'}<br>${btn('重試讀取狀態','id="retryNewsCache" '+(newsReading?'disabled':''))}<p class="ws-caption">這個按鈕只讀取後端已儲存結果，不重新擷取來源、不呼叫 AI；若停留本頁，30秒後也會重試。</p></div>`:''}<p class="ws-caption">${newsReading?'正在同步後端已儲存的新聞狀態…':demoMode?'你現在操作的是合成資料體驗，這裡不會自動抓取真實新聞，也沒有每日更新成功的紀錄。':'停留本頁每60秒讀取已儲存結果，處理中每2.5秒同步；這些讀取不會重新擷取新聞或呼叫模型。'}</p><div class="actions" style="justify-content:start;margin-top:16px"><button class="btn" data-page="settings">查看更新設定</button><a class="btn" href="https://openai.com/news/" target="_blank" rel="noopener noreferrer">OpenAI 官方新聞 ↗</a><a class="btn" href="https://www.cna.com.tw/list/afe.aspx" target="_blank" rel="noopener noreferrer">中央社財經 ↗</a></div></section>`}
function newsChannelStatus(channel){const shown=channel.items?.length||0,known=Number.isInteger(channel.candidate_count)&&channel.candidate_count>=0,candidates=known?channel.candidate_count:null,attempt=channel.last_attempt||newsData?.job?.started_at,results=Array.isArray(channel.source_results)?channel.source_results:[];let shortage='';if(channel.stale)shortage=known?`本次取得 ${candidates} 則候選；下方保留的是上次 ${shown} 則內容，不是本次新摘要。`:`本次候選數未提供；下方保留的是上次 ${shown} 則內容，不是本次新摘要。`;else if(shown<5){if(channel.shortfall_reason)shortage=channel.shortfall_reason;else if(known&&candidates<5)shortage=`本次來源僅取得 ${candidates} 則可核對候選，畫面列出 ${shown} 則；來源數量不足，不是漏載其餘新聞。`;else if(known)shortage=`本次有 ${candidates} 則可核對候選，但目前${channel.ai_generated?'AI摘要':'來源快訊'}只列出 ${shown} 則，尚未達到5則；未列出的候選不等於沒有其他新聞。`;else shortage='此批沒有提供來源候選數，無法判定缺額原因。'}return `<div class="ws-callout"><div class="ws-pair"><span>已顯示 / 目標</span><strong>${shown} / 5 則</strong></div><div class="ws-pair"><span>本次可核對候選</span><strong>${known?candidates+' 則':'未提供'}</strong></div><p class="ws-caption">最後內容：${esc(newsTime(channel.updated_at))}<br>最後嘗試：${esc(newsTime(attempt))}</p>${shortage?`<p class="ws-caption" data-news-shortfall>${esc(shortage)}</p>`:''}${!channel.stale&&shown===5&&channel.shortfall_reason?`<p class="ws-caption">${esc(channel.shortfall_reason)}</p>`:''}</div>${results.length?`<div class="ws-table"><table><caption>本次來源擷取狀態</caption><thead><tr><th>來源</th><th>結果</th><th>本次篇數</th></tr></thead><tbody>${results.map(r=>{const label=r.status==='ok'?'取得可用內容':r.status==='no_recent_content'?'近72小時無可用內容（非連線失敗）':r.status==='failed'?'擷取失敗':'狀態未提供',count=Number.isInteger(r.article_count)&&r.article_count>=0?r.article_count:'未提供';return `<tr><td>${esc(r.source)}</td><td>${esc(label)}${r.error_code?' · '+esc(r.error_code):''}</td><td>${esc(count)}</td></tr>`}).join('')}</tbody></table></div>`:'<p class="ws-caption">此批未提供逐來源狀態；候選數與下方錯誤記錄仍可核對。</p>'}`}
function newsDashboardEntry(){return `<section class="ws-card" style="margin-top:24px"><div class="ws-card-head"><div><span class="ws-kicker">NEWS / 每日新聞</span><h2>AI 與財經，每日重點。</h2></div><button class="btn primary" data-page="news">打開每日新聞 →</button></div><p class="ws-caption">${demoMode?'互動體驗尚未連線新聞服務；進入可查看排程設定與目前更新狀態。':'查看AI與財經各最多5則、來源日期、摘要與更新狀態。'}</p></section>`}
function wsNews(){const job=newsData?.job||{status:'idle'},channels=newsData?.channels||{},running=job.status==='running',topics=[['ai','AI 大小事','AI DAILY FIVE'],['finance','財經大小事','FINANCE DAILY FIVE']];return wsHeader('每日新聞 · AI 與財經。','NEWS / DAILY BRIEF','AI與財經各精選最多5則，附摘要、重要原因與原始來源。',btn(newsReading?'正在同步狀態…':running?'正在更新…':demoMode?'檢查更新狀態':'立即更新',`id="refreshNews" ${running||newsReading?'disabled':''}`,'primary'))+newsConnectionPanel()+`<div class="ws-callout ${job.status==='failed'?'ws-warning':''}" role="status"><strong>${running?'正在擷取新聞與整理摘要，尚未完成。':job.message||'等待首次更新。'}</strong><br>${newsData?.next_run?'下次排程：'+esc(newsTime(newsData.next_run))+'（台灣時間）':demoMode?'體驗頁不執行新聞連線；請啟動後端查看真實更新。':'尚未排定下次更新。'}<br>更新流程結束不代表每個來源都成功；請查看下方候選數、缺額原因與逐來源狀態。後端須持續運行，只採最近72小時可核對來源，未滿5則不湊數。</div><div class="ws-tabs">${[['all','全部'],['ai','AI 大小事'],['finance','財經大小事']].map(([id,label])=>`<button data-news-tab="${id}" class="${newsTab===id?'active':''}">${label}</button>`).join('')}<button data-page="settings">更新時間與API設定 ↗</button></div><div class="ws-grid ${newsTab==='all'?'two':''}" style="align-items:start">${topics.filter(([id])=>newsTab==='all'||newsTab===id).map(([id,title,kicker])=>{const channel=channels[id];return `<section><div class="section-head"><div><span class="ws-kicker">${kicker}</span><h2>${title}</h2></div>${badge(channel?.stale?'保留上次摘要':channel?.ai_generated?'AI精選摘要':'尚未生成AI摘要',channel?.ai_generated&&!channel.stale?'success':'')}</div>${channel?`<p class="ws-caption">資料日期 ${esc(channel.date)} · ${channel.ai_generated?'AI綜合時效、影響範圍與來源挑選':'僅按發布時間排列來源快訊'}</p>${newsChannelStatus(channel)}${channel.stale?'<div class="ws-callout ws-warning">本次沒有新資料，以下保留的是上次內容，不是今日更新。</div>':''}${(channel.errors||[]).map(e=>`<div class="ws-callout ws-warning">${esc(e.source)}：${esc(e.message)}${e.url?` <a href="${safeLink(e.url)}" target="_blank" rel="noopener noreferrer">來源 ↗</a>`:''}</div>`).join('')}<div style="display:grid;gap:18px;margin-top:18px">${(channel.items||[]).map((article,index)=>`<article class="ws-news"><div class="ws-kicker">0${index+1} / ${esc(article.source)}</div><h3>${esc(article.title)}</h3><p>${esc(channel.ai_generated?article.summary:article.excerpt||'來源僅提供標題，請閱讀原文。')}</p>${channel.ai_generated?`<div class="ws-callout" style="margin:14px 0"><strong>為什麼重要</strong><br>${esc(article.why)}</div>`:'<p class="ws-caption">來源簡介，未經AI摘要。</p>'}<p class="ws-caption">發布 ${esc(newsTime(article.published))}</p><a href="${safeLink(article.url)}" target="_blank" rel="noopener noreferrer">閱讀原始報導 ↗</a></article>`).join('')}</div>`:empty('等待第一份每日整理。',demoMode?'體驗頁不會製造新聞。正式後端會擷取來源，再交給AI篩選與摘要。':'此畫面會讀取後端已儲存的內容；如尚無內容，再按「立即更新」啟動擷取與摘要。')}</section>`}).join('')}</div><div class="ws-callout">AI摘要可能有疏漏，請以原始來源為準。這裡不提供即時報價或買賣建議，也不會將私人帳單送給新聞模型。</div>`}
function scheduleCard(){const schedule=ws.settings.news_schedule||{enabled:true,hour:8,minute:0};return `<section class="ws-card"><h2>News 每日更新</h2><p class="ws-caption">AI與財經各最多5則；新聞內容使用公開來源，不附私人帳單。</p><form id="newsScheduleForm"><div class="field"><label for="newsEnabled"><input id="newsEnabled" type="checkbox" ${schedule.enabled?'checked':''} style="width:auto"> 啟用每日更新</label></div><div class="ws-form-grid">${field('newsHourValue','台灣時間 · 小時',schedule.hour,'number')}${field('newsMinuteValue','分鐘',schedule.minute,'number')}</div><p class="ws-caption">後端關閉時不會執行；重新啟動且今日尚未更新時，會在指定時間之後補抓。連線或來源失敗不會補造5則。</p><div class="actions" style="justify-content:start">${btn('儲存更新時間','type="submit"','primary')}${btn('查看News','type="button" data-page="news"')}</div></form></section>`}

function safeLink(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}}
function stopNewsPolling(){clearTimeout(newsPoll);newsPoll=null;newsTicket++;newsReading=false}
function scheduleNewsPoll(){clearTimeout(newsPoll);newsPoll=null;if(page!=='news')return;const delay=newsReadError?30000:newsData?.job?.status==='running'?2500:60000;newsPoll=setTimeout(()=>{newsPoll=null;if(page==='news')loadNews(false)},delay)}
async function loadNews(refresh=false){clearTimeout(newsPoll);newsPoll=null;const ticket=++newsTicket;newsReading=true;newsReadError='';if(page==='news')draw();let ok=false;try{if(refresh&&!demoMode&&newsData?.job?.status!=='running'){await api('/api/news/refresh',{});if(ticket!==newsTicket)return false}const result=await api('/api/news');if(ticket!==newsTicket)return false;if(!result||typeof result.channels!=='object'||!result.channels||Array.isArray(result.channels)||typeof result.job!=='object'||!result.job)throw Error('新聞狀態格式不完整，未覆寫原內容');newsData=result;newsReadAt=new Date().toISOString();if(lastError.startsWith('新聞更新未完成'))lastError='';ok=true}catch(error){if(ticket!==newsTicket)return false;newsReadError='新聞狀態讀取未完成：'+error.message;notice(newsReadError)}finally{if(ticket===newsTicket){newsReading=false;if(page==='news')draw();scheduleNewsPoll()}}return ok}
function wsAssistant(){return wsHeader('問問你的數字。','FINANCIAL ASSISTANT','本機查詢直接讀取已計算資料；雲端AI另需Key與同意。',monthControl())+`<div class="ws-tabs"><button data-assistant-mode="local" class="${assistantMode==='local'?'active':''}">本機資料查詢</button><button data-assistant-mode="ai" class="${assistantMode==='ai'?'active':''}">雲端AI解讀</button></div>${assistantMode==='local'?'<p class="ws-caption">用下方按鈕查詢，答案由固定計算與來源資料組成，不會假裝理解任意問題。</p>':'<div class="ws-callout ws-warning">送出後會將所選月份的資產、負債、收支與分類彙總送至DeepSeek，你輸入的問題原文也會送至DeepSeek，請勿貼敏感明細。系統不附原始PDF或商家交易明細。請核對生成文字。<br><button class="textbtn" data-page="settings">設定雲端服務 ↗</button></div>'}<section class="ws-chat"><div class="ws-chat-log" id="workspaceChat"><div class="ws-bubble">從清楚的問題開始。你可以查這個月的收支、某一類支出，或看資產與應繳摘要。</div>${conversation.map(c=>`<div class="ws-bubble ${c.role==='user'?'user':''}">${esc(c.text)}</div>`).join('')}${assistantBusy?'<div class="ws-bubble" role="status">正在整理，尚未完成…</div>':''}</div>${assistantMode==='local'?`<div class="ws-suggestions">${['本月收支','餐飲支出','交通支出','資產配置','近期應繳','預算狀況'].map(q=>btn(q,`data-local-question="${q}" ${assistantBusy?'disabled':''}`)).join('')}</div>`:`<form class="ws-chat-form" id="aiChatForm"><input id="aiQuestion" placeholder="例如：請解釋我這個月的財務摘要" maxlength="1200" required aria-label="問題" ${assistantBusy?'disabled':''}><button class="btn primary" ${assistantBusy?'disabled':''}>${assistantBusy?'整理中…':'同意傳送摘要並提問'}</button></form>`}</section>`}
function localQuestion(q){let answer='';if(q==='本月收支')answer=`${month} 收入 ${fmt(summary.income)}，支出 ${fmt(summary.expense)}，結餘 ${plus(summary.balance)}。\n依據：已確認的 ${summary.transaction_count} 筆交易，含 ${summary.excluded_count} 筆排除生活收支的轉帳、投資或繳卡費。`;else if(q.endsWith('支出')){const cat=q.replace('支出',''),ts=db.transactions.filter(t=>t.date.startsWith(month)&&t.category===cat);answer=ts.length?`${month} ${cat}淨支出 ${fmt(ws.spending[cat])}。\n`+ts.map(t=>`${t.date} ${t.name} ${plus(t.amount)}｜${t.source}${t.page?' p.'+t.page:' 列'+(t.line||'—')}`).join('\n'):`${month} 尚無${cat}記錄，不代表實際沒有消費。`}else if(q==='資產配置')answer=ws.allocation.length?ws.allocation.map(a=>`${a.asset_class}：${fmt(a.value)}，占 ${number(a.actual).toFixed(1)}%${a.difference===null?'，尚未設定目標':'，對目標差額 '+plus(a.difference)}`).join('\n'):'尚未記錄資產，無法計算配置。';else if(q==='近期應繳')answer=upcomingBills().map(b=>`${b.due} ${b.name} ${fmt(b.amount)}`).join('\n')||'目前沒有待繳記錄；不代表已確認沒有欠款。';else answer=(ws.budgets||[]).map(b=>`${b.category}：支出 ${fmt(b.used)}／預算 ${fmt(b.limit)}，剩餘 ${fmt(b.remaining)}`).join('\n')||'這個月尚未設定分類預算。';conversation.push({role:'user',text:q},{role:'assistant',text:answer});draw();el('#workspaceChat').scrollTop=el('#workspaceChat').scrollHeight}
function wsSettings(){return wsHeader('你的工作區，由你決定。','PREFERENCES & DATA','外觀、面板、備份與可選服務，都放在這裡。')+`<div class="ws-grid two"><section class="ws-card"><h2>外觀與版面</h2><div class="field"><label for="workspaceTheme">顯示主題</label><select id="workspaceTheme"><option value="light" ${ws.settings.theme!=='dark'?'selected':''}>米白積木 / Paper</option><option value="dark" ${ws.settings.theme==='dark'?'selected':''}>深色積木 / Ink</option></select></div>${btn('調整儀表板面板','id="layoutFromSettings"')}<p class="ws-caption" style="margin-top:16px">面板可開關、排序，至少保留一個。所有頁面的資料共用同一份工作區。</p></section><section class="ws-card"><h2>備份與資料</h2><p class="ws-caption">JSON包含交易快照與規劃資料；尚未提供JSON一鍵還原。停止服務後複製SQLite檔，可保留完整文件核對與稽核記錄。</p><div class="actions" style="justify-content:start;margin-top:20px">${btn('匯出資料 JSON','id="jsonExport"','primary')}${btn('匯出本月 CSV','id="filteredCSV"')}</div>${demoMode?`<div class="ws-callout">體驗資料只屬於這個展示工作區。${btn('重設體驗資料','id="resetExperience"')}</div>`:'<div class="ws-callout">原始PDF不留存；本地資料庫未加密，請使用作業系統磁碟保護。</div>'}</section>${scheduleCard()}<section class="ws-card"><h2>雲端AI · DeepSeek</h2><p class="ws-caption">Key只在目前服務執行期間保存，不寫入資料庫、備份或瀏覽器。這不是你的ChatGPT訂閱額度。</p><form id="aiConfigForm"><div class="field"><label for="modelName">模型名稱</label><input id="modelName" value="deepseek-flash" maxlength="80" required ${demoMode?'disabled':''}></div><div class="field"><label for="modelKey">API Key</label><input id="modelKey" type="password" autocomplete="off" placeholder="僅送往你的本機服務" maxlength="512" ${demoMode?'disabled':''}></div><p class="ws-caption">${demoMode?'體驗模式不接收Key；請啟動本機後端後設定。':'未填Key並儲存會清除目前服務設定。你也可以用環境變數LEDGER_DEEPSEEK_API_KEY。'}</p><div class="actions" style="justify-content:start">${btn('儲存服務設定','type="submit" '+(demoMode?'disabled':''),'primary')}${btn('查詢連線設定','type="button" id="checkAI"')}</div><div id="aiStatus" class="ws-caption" aria-live="polite" style="margin-top:15px"></div></form></section><section class="ws-card"><h2>現在支援到哪裡？</h2>${pairs([['文件','文字PDF指定版型、CSV'],['財務資料','人工覆核＋來源回查'],['投資價格／匯率','手動估值，非即時行情'],['新聞','公開官方RSS，連線時取得'],['掃描OCR','尚未安裝／未提供'],['銀行帳號自動串接','不提供']])}<button class="textbtn" data-page="intro">看完整產品說明 ↗</button></section></div>`}

function field(name,label,value='',type='text',options=null,note='',required=true){const id='edit-'+name;let control;if(options)control=`<select id="${id}" name="${name}" ${required?'required':''}>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select>`;else control=`<input id="${id}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'step="any"':''} ${type==='text'?'maxlength="150"':''}>`;return `<div class="field"><label for="${id}">${label}</label>${control}${note?`<small>${note}</small>`:''}</div>`}
function entityFields(kind,item={}){const name=field('name','名稱',item.name||''),day=today();switch(kind){case 'budget':return name+field('month','預算月份',item.month||month,'month')+field('category','消費分類',item.category||'餐飲','text',['餐飲','交通','生活','保險','娛樂'])+field('limit','每月額度（TWD）',item.limit||'','number',null,'最多兩位小數；不會從帳戶扣款。');case 'goal':return name+field('target','目標金額（TWD）',item.target||'','number')+field('saved','目前已存（TWD）',item.saved||'0','number')+field('deadline','希望完成日期',item.deadline||'','date',null,'可留空；目標存款不再重複加到資產。',false);case 'holding':return name+field('symbol','代號',item.symbol||'','text',null,'例如0050或VOO；此版不會自動查價。',false)+field('asset_class','資產類別',item.asset_class||'台股與ETF','text',ASSET_CLASSES)+field('currency','原幣別',item.currency||'TWD','text',['TWD','USD','HKD'])+field('quantity','持有數量',item.quantity||'','number',null,'最多六位小數。')+field('cost_price','原幣單位成本',item.cost_price||'','number')+field('price','原幣手動現價',item.price||'','number')+field('fx','1原幣兌新台幣',item.fx||'1','number',null,'TWD固定為1，外幣使用這個手動匯率。')+field('as_of','估值日期',item.as_of||day,'date');case 'debt':return name+field('balance','剩餘本金（TWD）',item.balance||'','number')+field('rate','固定年利率（%）',item.rate||'0','number')+field('payment','每月還款（TWD）',item.payment||'','number')+field('due','下次應繳日',item.due||day,'date');case 'bill':return name+field('amount','應繳金額（TWD）',item.amount||'','number')+field('due','截止日期',item.due||day,'date')+field('recurrence','提醒週期',item.recurrence||'none','text',[['none','單次'],['monthly','每月'],['yearly','每年']])+field('status','繳款記錄',item.status||'unpaid','text',[['unpaid','待繳'],['paid','已標記繳清']]);case 'account':return name+field('asset_class','資產類別',item.asset_class||'現金與存款','text',ASSET_CLASSES)+field('value','目前快照金額（TWD）',item.value||'','number')+field('as_of','快照日期',item.as_of||day,'date');case 'investment_flow':return name+field('date','現金流日期',item.date||day,'date')+field('amount','金額（TWD）',item.amount||'','number',null,'投入負數；收回及期末估值正數。獨立於日常收支。');default:return ''}}
const KIND_NAMES={budget:'分類預算',goal:'儲蓄目標',holding:'投資持倉',debt:'手動貸款',bill:'繳費提醒',account:'手動資產',investment_flow:'投資現金流'};
function entityForm(kind,item=null,defaults={}){if(!KIND_NAMES[kind])return;const existing=item||defaults;dialog(`<h2>${item?'編輯':'新增'}${KIND_NAMES[kind]}</h2><form id="entityForm"><div class="ws-form-grid">${entityFields(kind,existing)}</div><p id="entityError" class="error" role="alert"></p><div class="actions"><button type="button" class="btn" data-close>取消</button><button class="btn primary">儲存${KIND_NAMES[kind]}</button></div></form>`);el('#entityForm').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target).entries());if(item){values.id=item.id;values.revision=item.revision}await perform(()=>api('/api/items/save',{kind,item:values}),{error:'#entityError',message:'已儲存'+KIND_NAMES[kind]})}}
async function perform(action,options={}){if(busy)return false;busy=true;let saved=false;const modal=el('#dialog'),controls=modal.open?[...modal.querySelectorAll('input,select,textarea,button')]:[];controls.forEach(c=>c.disabled=true);modal.oncancel=e=>{if(busy)e.preventDefault()};try{const result=await action();saved=true;if(options.close!==false&&modal.open)modal.close();if(options.refresh!==false)await reload();lastError='';draw();notice(options.message||'已儲存');return result}catch(e){if(saved){lastError='操作已儲存，但更新畫面失敗。請重新整理，勿重複送出。'+e.message;draw();notice(lastError)}else if(options.error&&el(options.error)){el(options.error).textContent=e.message}else{lastError=e.message;draw();notice(e.message)}return false}finally{busy=false;controls.forEach(c=>c.disabled=false)}}
function removeItem(item){dialog(`<h2>刪除這筆${KIND_NAMES[item.kind]}？</h2><p>${esc(item.name)}</p><p class="ws-caption">刪除後會重新計算工作區。這不會刪除上傳帳單。</p><p class="error" id="deleteError" role="alert"></p><div class="actions"><button class="btn" data-close>取消</button><button class="btn danger" id="confirmItemDelete">確認刪除</button></div>`);el('#confirmItemDelete').onclick=()=>perform(()=>api('/api/items/delete',{id:item.id,revision:item.revision}),{error:'#deleteError',message:'項目已刪除'})}
function manualTransaction(){dialog(`<h2>新增手動交易</h2><form id="manualForm"><div class="ws-form-grid">${field('date','交易日期',month+'-01','date')}${field('name','交易摘要')}${field('amount','金額（收入正／扣款負）','','number')}${field('category','分類','生活','text',cats)}</div><p class="error" id="manualError" role="alert"></p><div class="actions"><button type="button" class="btn" data-close>取消</button><button class="btn primary">確認新增</button></div></form>`);el('#manualForm').onsubmit=e=>{e.preventDefault();const transaction=Object.fromEntries(new FormData(e.target).entries());perform(()=>api('/api/transaction/create',{transaction}),{error:'#manualError',message:'交易已新增，統計已更新'})}}
function targetsDialog(){dialog(`<h2>設定你的配置比例</h2><p class="ws-caption">總和必須為100%，未填類別視為0。這是使用者自己的目標，不是系統給的買賣建議。</p><form id="targetForm"><div class="ws-form-grid">${ASSET_CLASSES.map((c,i)=>field('target'+i,c+'（%）',ws.settings.targets?.[c]||'0','number')).join('')}</div><p class="error" id="targetError" role="alert"></p><div class="actions"><button type="button" class="btn" data-close>取消</button><button class="btn primary">儲存並試算</button></div></form>`);el('#targetForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),targets={};ASSET_CLASSES.forEach((c,i)=>targets[c]=f.get('target'+i));perform(()=>api('/api/settings',{targets}),{error:'#targetError',message:'目標配置已更新'})}}
function layoutDialog(){let order=(ws.settings.widgets||Object.keys(WIDGET_NAMES)).slice(),selected=new Set(order);for(const k of Object.keys(WIDGET_NAMES))if(!order.includes(k))order.push(k);const paint=()=>{dialog(`<h2>排出你的財務視角。</h2><p class="ws-caption">勾選面板，使用箭頭排序。按儲存才會套用；取消不改動原版面。</p><div>${order.map((k,i)=>`<div class="ws-layout-row"><label><input type="checkbox" data-layout-key="${k}" ${selected.has(k)?'checked':''}>${WIDGET_NAMES[k]}</label><button class="btn small" data-layout-up="${i}" ${i===0?'disabled':''} aria-label="向上移動${WIDGET_NAMES[k]}">↑</button><button class="btn small" data-layout-down="${i}" ${i===order.length-1?'disabled':''} aria-label="向下移動${WIDGET_NAMES[k]}">↓</button></div>`).join('')}</div><p class="error" id="layoutError" role="alert"></p><div class="actions"><button class="btn" data-close>取消</button><button class="btn primary" id="saveLayout">儲存版面</button></div>`);const sync=()=>{selected=new Set([...el('#dialog').querySelectorAll('[data-layout-key]')].filter(i=>i.checked).map(i=>i.dataset.layoutKey))};el('#dialog').querySelectorAll('[data-layout-up],[data-layout-down]').forEach(b=>b.onclick=()=>{sync();const i=Number(b.dataset.layoutUp??b.dataset.layoutDown),j=i+(b.hasAttribute('data-layout-up')?-1:1);[order[i],order[j]]=[order[j],order[i]];el('#dialog').close();paint()});el('#saveLayout').onclick=()=>{sync();perform(()=>api('/api/settings',{widgets:order.filter(k=>selected.has(k))}),{error:'#layoutError',message:'面板已更新'})}};paint()}
async function showSchedule(id){try{const data=await api('/api/debt/schedule?id='+encodeURIComponent(id));dialog(`<h2>固定利率攤還試算</h2><p class="ws-caption">${esc(data.assumption)}</p><div class="ws-callout">已計 ${data.rows.length} 期 · 總利息 ${fmt(data.interest)} · ${data.paid_off?'可在試算期間還清':'600期內尚未還清'}</div><div class="ws-table"><table><thead><tr><th>期數</th><th>還款</th><th>利息</th><th>本金</th><th>剩餘本金</th></tr></thead><tbody>${data.rows.slice(0,60).map(r=>`<tr><td>${r.period}</td><td>${fmt(r.payment)}</td><td>${fmt(r.interest)}</td><td>${fmt(r.principal)}</td><td>${fmt(r.remaining)}</td></tr>`).join('')}</tbody></table></div><p class="ws-caption">此處顯示前60期。${data.rows.length>60?'完整結果可下載。':''}</p><div class="actions">${btn('下載完整試算','id="downloadSchedule"')}${btn('關閉','data-close')}</div>`);el('#downloadSchedule').onclick=()=>download('loan-schedule.json',JSON.stringify(data,null,2),'application/json')}catch(e){notice(e.message)}}
function shiftDate(value,recurrence){const [y,m,d]=value.split('-').map(Number),ny=recurrence==='yearly'?y+1:m===12?y+1:y,nm=recurrence==='yearly'?m:m===12?1:m+1,days=new Date(ny,nm,0).getDate();return `${ny}-${String(nm).padStart(2,'0')}-${String(Math.min(d,days)).padStart(2,'0')}`}
function filteredExport(){const rows=filteredTransactions(),cell=v=>{let s=String(v);if(/^\s*[=+@-]/.test(s)&&!/^\-?\d+(\.\d+)?$/.test(s)||/^[\t\r\n]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};download('ledger-filtered-'+month+'.csv','\uFEFFdate,description,amount,category,source\r\n'+rows.map(t=>[t.date,t.name,t.amount,t.category,t.source].map(cell).join(',')).join('\r\n'),'text/csv')}
async function changeMonth(next){if(!/^(?:19\d{2}|20\d{2}|21\d{2}|2200)-(0[1-9]|1[0-2])$/.test(next)){notice('請選擇有效月份');return}const loaded=summary.month||ws.month||month,ticket=++monthRequest;month=next;txPage=1;try{await reload();if(ticket===monthRequest){lastError='';draw()}}catch(error){if(ticket!==monthRequest)return;month=summary.month||loaded;lastError=error.message;draw()}}
function bindTransactionResults(){document.querySelectorAll('[data-tx-page]').forEach(b=>b.onclick=()=>{txPage=Number(b.dataset.txPage);el('#transactionResults').innerHTML=transactionRows();bindTransactionResults()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editTransaction(b.dataset.edit));document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>sourceDialog(b.dataset.source))}
bind=function(){coreBind();document.querySelectorAll('[data-news-tab]').forEach(b=>b.onclick=()=>{newsTab=b.dataset.newsTab;draw()});el('#newsScheduleForm')?.addEventListener('submit',e=>{e.preventDefault();const news_schedule={enabled:el('#newsEnabled').checked,hour:Number(el('#edit-newsHourValue').value),minute:Number(el('#edit-newsMinuteValue').value)};perform(()=>api('/api/settings',{news_schedule}),{close:false,message:'每日News更新時間已儲存；後端需持續運行'})});document.querySelectorAll('[data-widget]').forEach(card=>{card.ondragstart=e=>e.dataTransfer.setData('text/plain',card.dataset.widget);card.ondragover=e=>e.preventDefault();card.ondrop=e=>{e.preventDefault();const from=e.dataTransfer.getData('text/plain'),to=card.dataset.widget,order=(ws.settings.widgets||Object.keys(WIDGET_NAMES)).slice();if(!order.includes(from)||!order.includes(to)||from===to)return;order.splice(order.indexOf(from),1);order.splice(order.indexOf(to),0,from);perform(()=>api('/api/settings',{widgets:order}),{close:false,message:'面板順序已儲存'})}});document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();el('#'+a.dataset.scroll)?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})});document.querySelectorAll('[data-add-kind]').forEach(b=>b.onclick=()=>entityForm(b.dataset.addKind));document.querySelectorAll('[data-item-edit]').forEach(b=>b.onclick=()=>{const item=ws.items.find(i=>i.id===b.dataset.itemEdit);if(item)entityForm(item.kind,item)});document.querySelectorAll('[data-item-delete]').forEach(b=>b.onclick=()=>{const item=ws.items.find(i=>i.id===b.dataset.itemDelete);if(item)removeItem(item)});el('#workspaceMonth')?.addEventListener('change',e=>changeMonth(e.target.value));el('#txSearch')?.addEventListener('input',e=>{txQuery=e.target.value;txPage=1;el('#transactionResults').innerHTML=transactionRows();bindTransactionResults()});el('#txCategory')?.addEventListener('change',e=>{txCategory=e.target.value;txPage=1;draw()});el('#txDirection')?.addEventListener('change',e=>{txDirection=e.target.value;txPage=1;draw()});bindTransactionResults();el('#filteredCSV')?.addEventListener('click',filteredExport);el('#manualTransaction')?.addEventListener('click',manualTransaction);document.querySelectorAll('[data-spending-category]').forEach(b=>b.onclick=()=>{txCategory=b.dataset.spendingCategory;txQuery='';txPage=1;goto('transactions')});document.querySelectorAll('[data-select-month]').forEach(b=>b.onclick=()=>changeMonth(b.dataset.selectMonth));el('#copyBudgets')?.addEventListener('click',()=>perform(()=>api('/api/budgets/copy',{month}),{close:false,message:'已沿用上月尚未設定的分類預算'}));['layoutButton','layoutFromSettings'].forEach(id=>el('#'+id)?.addEventListener('click',layoutDialog));['allocationTargets','allocationTargetsSecond'].forEach(id=>el('#'+id)?.addEventListener('click',targetsDialog));el('#takeSnapshot')?.addEventListener('click',()=>perform(()=>api('/api/snapshot',{day:today()}),{close:false,message:'今日淨值快照已保存'}));el('#workspaceTheme')?.addEventListener('change',e=>perform(()=>api('/api/settings',{theme:e.target.value}),{close:false,message:'顯示主題已更新'}));document.querySelectorAll('[data-schedule]').forEach(b=>b.onclick=()=>showSchedule(b.dataset.schedule));document.querySelectorAll('[data-bill-toggle]').forEach(b=>b.onclick=()=>{const item=ws.items.find(i=>i.id===b.dataset.billToggle);if(item)perform(()=>api('/api/items/save',{kind:'bill',item:{...item,status:item.status==='paid'?'unpaid':'paid'}}),{close:false,message:'已更新提醒狀態；未自動新增付款交易'})});document.querySelectorAll('[data-bill-next]').forEach(b=>b.onclick=()=>{const item=ws.items.find(i=>i.id===b.dataset.billNext);if(item)entityForm('bill',null,{...item,id:undefined,revision:undefined,due:shiftDate(item.due,item.recurrence),status:'unpaid'})});document.querySelectorAll('[data-goal-fund]').forEach(b=>b.onclick=()=>{const item=ws.items.find(i=>i.id===b.dataset.goalFund);if(item)entityForm('goal',item)});el('#calculateXirr')?.addEventListener('click',async()=>{try{const result=await api('/api/xirr',{flows:items('investment_flow')});el('#xirrResult').innerHTML=`<div class="ws-callout">XIRR：<strong>${result.percent}%</strong><br>${esc(result.assumption)}</div>`}catch(e){el('#xirrResult').innerHTML=`<div class="ws-callout ws-warning" role="alert">${esc(e.message)}</div>`}});el('#refreshNews')?.addEventListener('click',()=>loadNews(true));el('#retryNewsCache')?.addEventListener('click',()=>loadNews(false));document.querySelectorAll('[data-assistant-mode]').forEach(b=>b.onclick=()=>{if(assistantBusy)return;assistantMode=b.dataset.assistantMode;draw()});document.querySelectorAll('[data-local-question]').forEach(b=>b.onclick=()=>localQuestion(b.dataset.localQuestion));el('#aiChatForm')?.addEventListener('submit',async e=>{e.preventDefault();if(assistantBusy)return;const question=el('#aiQuestion').value.trim();if(!question)return;conversation.push({role:'user',text:question});assistantBusy=true;draw();try{const response=await api('/api/ai/chat',{month,question,consent:true});conversation.push({role:'assistant',text:response.answer+'\n\n'+response.scope})}catch(error){conversation.push({role:'assistant',text:'未能完成雲端解讀：'+error.message})}finally{assistantBusy=false;draw();el('#workspaceChat').scrollTop=el('#workspaceChat').scrollHeight}});el('#aiConfigForm')?.addEventListener('submit',async e=>{e.preventDefault();if(demoMode)return;const key=el('#modelKey').value,model=el('#modelName').value;el('#modelKey').value='';try{const status=await api('/api/ai/configure',{key,model});el('#aiStatus').textContent=status.configured?'已設定服務Key；模型可用性須以實際提問確認。':'已清除服務Key。'}catch(error){el('#aiStatus').textContent=error.message}});el('#checkAI')?.addEventListener('click',async()=>{try{const status=await api('/api/ai/status');el('#aiStatus').textContent=status.configured?'Key已設定 · 模型 '+status.model+'（未代表已成功呼叫）':'尚未設定Key，仍可使用本機查詢。'}catch(error){el('#aiStatus').textContent=error.message}});el('#resetExperience')?.addEventListener('click',()=>{dialog('<h2>重設體驗工作區？</h2><p class="ws-caption">這會清除目前展示內的修改，回到合成範例。可先從設定匯出JSON。</p><div class="actions"><button class="btn" data-close>取消</button><button class="btn danger" id="confirmResetExperience">確認重設</button></div>');el('#confirmResetExperience').onclick=()=>perform(()=>api('/api/demo/reset',{}),{message:'體驗資料已重設'})})};
